Разная длина или лишний Character оставляют ненулевую частоту.

func compressed(_ text: String) -> String {
    var runs: [(character: Character, count: Int)] = []
    for character in text {
        if let last = runs.last, last.character == character {
            runs[runs.count - 1].count += 1
        } else {
            runs.append((character, 1))
        }
    }
    var result = ""
    for run in runs {
        result += run.count > 1 ? "\(run.character)\(run.count)"
                                : String(run.character)
    }
    return result
}
assert(compressed("aaabcc") == "a3bc2")
assert(compressed("abab") == "abab")
assert(compressed("") == "")
assert(compressed("👨‍👩‍👧‍👦👨‍👩‍👧‍👦") == "👨‍👩‍👧‍👦2")

