Первый проход считает частоты, второй идёт по строке, а не по словарю: порядок словаря не обещан. O(n) времени, память — по счётчику на каждый разный символ.

func index(of target: Int, in sorted: [Int]) -> Int? {
    var low = 0
    var high = sorted.count - 1
    while low <= high {
        let middle = low + (high - low) / 2
        if sorted[middle] == target { return middle }
        if sorted[middle] < target {
            low = middle + 1
        } else {
            high = middle - 1
        }
    }
    return nil
}
assert(index(of: 7, in: [1, 3, 7, 9]) == 2)
assert(index(of: 4, in: [1, 3, 7, 9]) == nil)
assert(index(of: 9, in: [9]) == 0)
assert(index(of: 1, in: []) == nil)

Инвариант: если target есть, он лежит в low...high. Каждое сравнение отбрасывает половину. Для пустого массива high = -1, и цикл не начинается.

func rotatedRight(_ values: [Int], by steps: Int) -> [Int] {
    guard !values.isEmpty else { return [] }
    let shift = steps % values.count
    let cut = values.count - shift
    return Array(values[cut...] + values[..<cut])
}
assert(rotatedRight([1, 2, 3, 4, 5], by: 2) == [4, 5, 1, 2, 3])
assert(rotatedRight([1, 2, 3, 4, 5], by: 7) == [4, 5, 1, 2, 3])
assert(rotatedRight([1, 2], by: 0) == [1, 2])
assert(rotatedRight([], by: 3) == [])

steps % count убирает полные обороты: 7 для пяти элементов — то же, что 2. Хвост из shift элементов уходит вперёд. Пустой вход проверяем до остатка: деление на ноль уронило бы программу.

func mergeRanges(_ ranges: [ClosedRange<Int>]) -> [ClosedRange<Int>] {
    let sorted = ranges.sorted { $0.lowerBound < $1.lowerBound }
    var result: [ClosedRange<Int>] = []
    for range in sorted {
        if let last = result.last, range.lowerBound <= last.upperBound {
            let upper = max(last.upperBound, range.upperBound)
            result[result.count - 1] = last.lowerBound...upper
        } else {
            result.append(range)
        }
    }
    return result
}
assert(mergeRanges([5...7, 1...3, 2...4]) == [1...4, 5...7])
assert(mergeRanges([1...2, 2...5]) == [1...5])
assert(mergeRanges([1...2, 3...4]) == [1...2, 3...4])
assert(mergeRanges([1...10, 2...3]) == [1...10])
assert(mergeRanges([]) == [])

После сортировки по началу новый интервал может пересечься только с последним склеенным. max берёт дальнюю границу: 1...10 поглощает 2...3. Сортировка — O(n log n), проход — O(n).

func longestDistinct(_ text: String) -> Int {
    let values = Array(text)
    var last: [Character: Int] = [:]
    var left = 0, best = 0
    for right in values.indices {
        if let previous = last[values[right]], previous >= left {
            left = previous + 1
        }
        last[values[right]] = right
        best = max(best, right - left + 1)
    }
    return best
}
assert(longestDistinct("abba") == 2)
assert(longestDistinct("👨‍👩‍👧‍👦а👨‍👩‍👧‍👦б") == 3)
assert(longestDistinct("") == 0)

left не двигается назад; повтор вне текущего окна не сужает его.

func balanced(_ text: String) -> Bool {
    let pairs: [Character: Character] = [")": "(", "]": "[", "}": "{"]
    var stack: [Character] = []
    for character in text {
        if "([{".contains(character) {
            stack.append(character)
        } else if let opening = pairs[character] {
            guard stack.popLast() == opening else { return false }
        } else { return false }
    }
    return stack.isEmpty
}
assert(balanced("([]){}"))
assert(!balanced("([)]"))
assert(!balanced("("))
assert(balanced(""))
assert(!balanced("a"))

